#![allow(unused_imports)]
use verus::prelude::*;

verus! {

    /// Takes elements from `arr` at the positions specified in `indices`.
    /// 
    /// Requirements:
    /// - For every `i < indices.len()`, `indices[i] < arr.len()`.
    /// 
    /// Ensures:
    /// - The returned vector has length equal to `indices.len()`.
    /// - For every `i < indices.len()`, `result[i] == arr[indices[i]]`.
    pub fn take(arr: Vec<f32>, indices: Vec<usize>) -> Vec<f32>
        requires
            // All indices are in-bounds for `arr`
            forall |i: usize| i < indices.len() ==> indices[i] < arr.len(),
        ensures
            // Output length matches indices length
            |result: Vec<f32>| result.len() == indices.len(),
        ensures
            // Each output element is the corresponding element from `arr`
            |result: Vec<f32>| forall |i: usize| i < indices.len() ==> result[i] == arr[indices[i]],
    {
        let mut result: Vec<f32> = Vec::new();
        let mut i: usize = 0;

        // Build up `result` one element at a time
        while i < indices.len() 
            invariant i <= indices.len();
            invariant result.len() == i;
            invariant forall |j: usize| j < i ==> result[j] == arr[indices[j]];
            decreases indices.len() - i;
        {
            let idx = indices[i];
            let val = arr[idx];
            result.push(val);
            i += 1;
        }

        result
    }

}